CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(20),role ENUM('admin','petugas','masyarakat') DEFAULT 'masyarakat',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE report_categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL);
CREATE TABLE locations(id INT AUTO_INCREMENT PRIMARY KEY,kabupaten VARCHAR(60),kecamatan VARCHAR(60),address VARCHAR(255),lat DECIMAL(10,7),lng DECIMAL(10,7));
CREATE TABLE reports(id INT AUTO_INCREMENT PRIMARY KEY,ticket VARCHAR(30) UNIQUE,user_id INT,category_id INT,location_id INT,title VARCHAR(150),description TEXT,reporter_name VARCHAR(100),phone VARCHAR(20),status ENUM('Menunggu','Diverifikasi','Ditugaskan','Dalam Proses','Selesai','Ditolak') DEFAULT 'Menunggu',is_demo TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(category_id) REFERENCES report_categories(id),FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE report_images(id INT AUTO_INCREMENT PRIMARY KEY,report_id INT,file VARCHAR(255),FOREIGN KEY(report_id) REFERENCES reports(id) ON DELETE CASCADE);
CREATE TABLE officers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE,area VARCHAR(60),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE report_assignments(id INT AUTO_INCREMENT PRIMARY KEY,report_id INT,officer_id INT,assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(report_id) REFERENCES reports(id) ON DELETE CASCADE,FOREIGN KEY(officer_id) REFERENCES officers(id) ON DELETE CASCADE);
CREATE TABLE report_updates(id INT AUTO_INCREMENT PRIMARY KEY,report_id INT,user_id INT,status VARCHAR(30),note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(report_id) REFERENCES reports(id) ON DELETE CASCADE);
CREATE TABLE waste_banks(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),address VARCHAR(255),manager VARCHAR(100),phone VARCHAR(20),kabupaten VARCHAR(60),lat DECIMAL(10,7),lng DECIMAL(10,7),hours VARCHAR(80),active TINYINT DEFAULT 1,is_demo TINYINT DEFAULT 0);
CREATE TABLE waste_bank_categories(id INT AUTO_INCREMENT PRIMARY KEY,waste_bank_id INT,waste_type VARCHAR(60),price INT DEFAULT 0,FOREIGN KEY(waste_bank_id) REFERENCES waste_banks(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,message VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
